<script setup>
import {inject,onMounted,onBeforeUnmount,ref,reactive} from 'vue'
import {api,errorText,isAdmin,copyText,t} from '../state'
import PaymentCard from './PaymentCard.vue'
import ConfirmDialog from './ConfirmDialog.vue'
import MerchantDialog from './MerchantDialog.vue'
const ledgerNames={payment:'支付收入',available:'转为可结算',registration:'注册费',deposit:'真实充保证金',deposit_adjust:'手动充保证金',deposit_release:'保证金解冻',refund_hold:'退款预留',refund_success:'退款成功',refund_failed:'退款释放',settlement_request:'申请结算',settlement_paid:'登记出款',settlement_cancel:'取消结算',invite_release:'邀请返现释放'}
const accountNames={pending:'待结算',available:'可用余额',deposit:'保证金',refund_hold:'退款冻结',settlement_hold:'结算冻结',commission_hold:'返现冻结'}
const c=inject('console'),merchantDialog=ref(null),data=ref(null),domains=ref([]),host=ref(''),busy=ref(false),error=ref(''),notice=ref(''),bill=ref(null),deposit=ref('100.00'),settleAmount=ref(''),beneficiary=reactive({channel:'alipay',account:'',name:''}),release=ref(null)
let timer
async function load(){try{const [account,list]=await Promise.all([api('/api/account'),api('/api/domains')]);data.value=account;domains.value=list.domains;if(!beneficiary.account)Object.assign(beneficiary,account.beneficiary);if(bill.value){const result=await api(`/api/v1/payments/${bill.value.out_trade_no}`);bill.value=result.order}}catch(e){error.value=errorText(e)}}
async function act(kind,body={}){busy.value=true;error.value='';notice.value='';try{if(kind==='bill'){bill.value=(await api('/api/account/bill',{method:'POST',body:JSON.stringify(body)})).order}else if(kind==='beneficiary'){const value={channel:beneficiary.channel,account:beneficiary.account||'',name:beneficiary.name||''};await api('/api/account/beneficiary',{method:'PUT',body:JSON.stringify(value)});notice.value='结算账户已保存'}else if(kind==='settle'){await api('/api/account/settlements',{method:'POST',body:JSON.stringify({amount:settleAmount.value})});notice.value='结算申请已提交，等待出款'}else if(kind==='domain'){await api('/api/domains',{method:'POST',body:JSON.stringify({host:host.value})});host.value='';notice.value='域名申请已提交'}else if(kind==='review'){await api(`/api/admin/domains/${body.id}`,{method:'POST',body:JSON.stringify({status:body.status})})}else if(kind==='release'){await api(`/api/account/deposits/${release.value}/release`,{method:'POST'});release.value=null;notice.value='保证金已转入可用余额'}await load()}catch(e){error.value=errorText(e)}finally{busy.value=false}}
async function invite(){await copyText(`${location.origin}/register?invite=${data.value.access.invite_code}`);notice.value='邀请链接已复制'}
onMounted(()=>{load();timer=setInterval(()=>{if(!document.hidden&&!busy.value)load()},5000)});onBeforeUnmount(()=>clearInterval(timer))
</script>
<template><div class="console-page-heading"><h2>{{ t('账户与结算','Account & settlements') }}</h2><button class="button button-secondary" type="button" @click="merchantDialog.open()">{{ t('接口配置','Merchant API') }}</button></div><MerchantDialog ref="merchantDialog"/><p v-if="error" class="error-box" role="alert">{{ error }}</p><p v-if="notice" role="status">{{ notice }}</p><div v-if="data" class="operation-settings">
<section class="hig-card settings-card"><h3>商户接入状态</h3><div class="setting-value-row"><span>审核状态</span><b>{{ ({pending:'等待审核',approved:'审核通过',rejected:'审核未通过'})[data.access.review] }}</b><small>{{ data.access.review_note }}</small></div><div class="setting-value-row"><span>注册服务费</span><b>{{ data.access.registration_paid?'已完成':'待支付 ￥'+data.access.registration_fee }}</b><button v-if="!data.access.registration_paid" class="button" :disabled="busy" @click="act('bill',{purpose:'registration'})">支付注册费</button></div><p v-if="data.access.risk_hold" class="error-box">商户收款已暂停 · {{ data.access.risk_reason }}</p><div v-if="data.rules.invite_enabled" class="setting-value-row"><span>邀请新商户</span><button class="button button-secondary" @click="invite">复制邀请链接</button></div></section>
<div class="account-balance-grid"><section v-for="item in [['pending','待结算'],['available','可用余额'],['deposit','保证金'],['settlement_hold','结算冻结'],['refund_hold','退款冻结'],['commission_hold','待释放返现']]" :key="item[0]" class="hig-card"><span>{{ item[1] }}</span><strong>￥{{ data.balances[item[0]] }}</strong></section></div>
<section v-if="data.access.deposit_required" class="hig-card settings-card"><h3>商户保证金</h3><p class="field-hint">最低充值 ￥{{ data.access.deposit_minimum }}，至少冻结 {{ data.access.deposit_freeze_days }} 天</p><form class="mail-test-row" @submit.prevent="act('bill',{purpose:'deposit',amount:deposit})"><label>充值金额<input v-model="deposit" inputmode="decimal" required/></label><button class="button" :disabled="busy">生成保证金付款单</button></form><div v-for="item in data.deposits" :key="item.number" class="setting-value-row"><code>{{ item.source === 'manual' ? '手动充保证金' : '真实充保证金' }} · {{ item.number }}</code><span>￥{{ ((item.remaining ?? item.cents)/100).toFixed(2) }} · {{ new Date(item.release_at*1000).toLocaleDateString() }}</span><button v-if="item.status==='frozen'" class="text-link" @click="release=item.number">申请解除冻结</button><span v-else>已释放</span></div></section>
<PaymentCard v-if="bill" :key="bill.out_trade_no" :order="bill"/>
<section class="hig-card settings-card"><h3>结算账户</h3><form @submit.prevent="act('beneficiary')"><div class="policy-form-grid"><label>出款方式<select v-model="beneficiary.channel"><option value="alipay">支付宝</option><option value="bank">银行卡</option></select></label><template><label>收款人姓名<input v-model="beneficiary.name" required/></label><label>收款账号<input v-model="beneficiary.account" required/></label></template></div><button class="button" :disabled="busy">保存结算账户</button></form><form v-if="['manual','both'].includes(data.rules.settlement_mode)" class="mail-test-row" @submit.prevent="act('settle')"><label>申请结算金额（至少 ￥{{ data.rules.settlement_minimum }}）<input v-model="settleAmount" inputmode="decimal" required/></label><button class="button" :disabled="busy">申请结算</button></form><div v-for="row in data.settlements" :key="row.id" class="setting-value-row"><code>{{ row.id }}</code><span>￥{{ (row.gross/100).toFixed(2) }} · 手续费 ￥{{ (row.fee/100).toFixed(2) }}</span><b>{{ ({pending:'待出款',paid:'已登记出款',cancel:'已取消'})[row.status] }}</b></div></section>
<section class="hig-card settings-card"><h3>授权支付域名</h3><form v-if="data.rules.domain_add||isAdmin" class="mail-test-row" @submit.prevent="act('domain')"><label>域名<input v-model="host" placeholder="shop.example.com" required/></label><button class="button" :disabled="busy">申请添加</button></form><div v-for="domain in domains" :key="domain.id" class="setting-value-row"><span>{{ domain.host }} <small v-if="isAdmin">{{ domain.email }}</small></span><b>{{ ({pending:'待审核',approved:'已授权',rejected:'已拒绝'})[domain.status] }}</b><div v-if="isAdmin" class="inline-actions"><button class="text-link" @click="act('review',{id:domain.id,status:'approved'})">通过</button><button class="text-link" @click="act('review',{id:domain.id,status:'rejected'})">拒绝</button></div></div></section>
<section class="hig-card settings-card"><h3>账务流水</h3><p v-if="!data.entries.length" class="field-hint">暂无账务流水，支付成功后将按订单快照记账</p><div v-for="(entry,index) in data.entries" :key="entry.id+'-'+index" class="setting-value-row"><span>{{ ledgerNames[entry.kind]||entry.kind }} · {{ accountNames[entry.account]||entry.account }}</span><code>{{ entry.reference }}</code><b>{{ entry.cents<0?'+':'−' }}￥{{ (Math.abs(entry.cents)/100).toFixed(2) }}</b></div></section>
</div><ConfirmDialog :open="!!release" title="申请解除保证金冻结" description="冻结期与待处理交易由服务器复查，通过后保证金转入可用余额，实际出款需申请结算" :busy="busy" @cancel="release=null" @confirm="act('release')"/></template>
